import { createOrganizationAction, createUserAction } from '@/app/actions';
import { Empty, PageHeader, Status } from '@/components/ui';
import { api } from '@/lib/api';

type Organization = { id: string; organizationId: string; name: string; type: string; mspId: string | null; status: string; _count: { users: number } };
type User = { id: string; name: string; email: string | null; role: string; status: string; lastLoginAt: string | null; organization: { name: string; organizationId: string } | null };

export default async function DirectoryPage() {
  const [orgs, people] = await Promise.all([api<{ organizations: Organization[] }>('/api/admin/organizations?limit=100'), api<{ users: User[] }>('/api/admin/users?limit=100')]);
  return <main className="page"><PageHeader kicker="Consortium governance" title="Organizations and operators" description="Provision institutions and privileged operators. Public registration cannot create supply-chain roles." />
    <section className="split-grid directory-grid"><article className="panel"><div className="panel-head"><div><p className="eyebrow">Membership</p><h2>Organizations</h2></div></div>{orgs.organizations.length ? <div className="directory-list">{orgs.organizations.map((org) => <div key={org.id}><span className="org-monogram">{org.type.slice(0, 2)}</span><div><strong>{org.name}</strong><code>{org.organizationId} · {org.mspId ?? 'No MSP'}</code></div><div><Status>{org.status}</Status><small>{org._count.users} users</small></div></div>)}</div> : <Empty>No organizations.</Empty>}
      <details><summary>Add organization</summary><form action={createOrganizationAction} className="form-grid"><input name="organization_id" placeholder="Organization ID" required/><input name="name" placeholder="Legal name" required/><select name="type"><option>FACTORY</option><option>LAB</option><option>DISTRIBUTOR</option><option>RETAILER</option><option>REGULATOR</option></select><input name="msp_id" placeholder="MSP ID (optional)"/><button className="button primary" type="submit">Create organization</button></form></details></article>
      <article className="panel"><div className="panel-head"><div><p className="eyebrow">Access</p><h2>Privileged operators</h2></div></div>{people.users.length ? <div className="directory-list">{people.users.map((user) => <div key={user.id}><span className="org-monogram person">{user.name.slice(0, 2).toUpperCase()}</span><div><strong>{user.name}</strong><code>{user.email} · {user.role}</code></div><Status>{user.status}</Status></div>)}</div> : <Empty>No users.</Empty>}
      <details><summary>Provision operator</summary><form action={createUserAction} className="form-grid"><input name="name" placeholder="Full name" required/><input name="email" type="email" placeholder="Email" required/><input name="password" type="password" minLength={12} placeholder="Temporary password (12+ chars)" required/><select name="role"><option>TRANSPORTER</option><option>LABTECH</option><option>FACTORYWORKER</option><option>QCMANAGER</option><option>DISTRIBUTOR</option><option>ADMIN</option></select><select name="organization_id" required><option value="">Choose organization</option>{orgs.organizations.map((org) => <option value={org.id} key={org.id}>{org.name}</option>)}</select><button className="button primary" type="submit">Provision user</button></form></details></article></section>
  </main>;
}
